export const tileNames = ["grass", "objects", "Assets_source"] as const;

const gameTiles: Record<(typeof tileNames)[number], string> = {
  grass: "assets/locations/grass_32.png",
  objects: "assets/locations/objects.png",
  Assets_source: "assets/locations/mapTiles/Assets_source.png",
};

const staticResources = {}

export const gameConfig = {
  names: {
    tiles: {},
    map: "gameMap",
  },
  tiles: gameTiles,

  gamePlay: {
    /**Chance that the random box will be locked. From 0 to 100 */
    randomBoxLockChance: 25,
    randomItemsMaxAmount: 5,
  },

  light: {
    defaultColor: 0xff860c,
    defaultIntensity: 1,
  },
  dayCircleTimeInRealSeconds: 10,
} as const;
